def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'

    opp_d = 0
    my_d = 0
    for a, b in history:
        if a == 'D':
            my_d += 1
        if b == 'D':
            opp_d += 1

    after_c_total = 0
    after_d_total = 0
    after_c_defect = 0
    after_d_coop = 0
    for i in range(1, n):
        prev = history[i - 1][0]
        curr = history[i][1]
        if prev == 'C':
            after_c_total += 1
            if curr == 'D':
                after_c_defect += 1
        else:
            after_d_total += 1
            if curr == 'C':
                after_d_coop += 1

    start = n - 12
    if start < 0:
        start = 0
    r_opp_d = 0
    for i in range(start, n):
        if history[i][1] == 'D':
            r_opp_d += 1

    persistent = False
    if n >= 2 and opp_d == n:
        persistent = True
    elif n >= 10 and opp_d >= 8:
        persistent = True
    elif n >= 20 and opp_d * 3 >= n * 2:
        persistent = True
    elif n >= 12 and r_opp_d >= 7:
        persistent = True
    elif n >= 20 and opp_d * 2 >= n and r_opp_d >= 5:
        persistent = True

    if after_c_total >= 6 and after_d_total >= 6:
        if after_c_defect * 100 >= 55 * after_c_total and after_d_coop * 100 >= 55 * after_d_total:
            return 'D'

    if persistent:
        return 'D'

    last_my, last_opp = history[-1]
    prev_my = history[-2][0] if n >= 2 else last_my

    condc = 0
    i = n - 1
    while i >= 0 and history[i][0] == 'D' and history[i][1] == 'C':
        condc += 1
        i -= 1

    if opp_d == 0:
        if my_d > 0:
            return 'D'
        if n >= 90 and rng.random() < 0.18:
            return 'D'
        return 'C'

    if n >= 90 and opp_d <= 2 and condc >= 1:
        return 'D'

    if last_opp == 'D':
        if last_my == 'D':
            if r_opp_d >= 4 and opp_d >= 4:
                return 'D'
            if n >= 8 and opp_d >= 6 and opp_d * 2 >= n:
                return 'D'
            return 'C'
        else:
            if prev_my == 'D':
                if r_opp_d >= 5 and opp_d >= 5:
                    return 'D'
                return 'C'
            if n >= 2 and history[-2][1] == 'D' and history[-2][0] == 'C':
                return 'D'
            return 'D'
    else:
        if last_my == 'D':
            if condc >= 2 and opp_d <= max(4, n // 4):
                return 'D'
            if n >= 90 and opp_d <= 2:
                return 'D'
            if opp_d <= max(1, n // 25) and rng.random() < 0.12:
                return 'D'
            return 'C'
        else:
            if n >= 90 and opp_d <= 2 and rng.random() < 0.1:
                return 'D'
            return 'C'
